-- 7. Contrôle : nombre de comptes par catégorie (à comparer avec la page Administration)
select categorie, count(*) as comptes, sum(nb_actions) as actions
  from public.admin_comptes
 where email like '%@recette.invalid'
 group by categorie
 order by categorie;

